/**
 * What the artifact IS — one flat value, so a single (possibly bound) field decides everything.
 * PDF/DOCX/PPTX all render through the pdf preview pipeline (DOCX/PPTX arrive converted to PDF;
 * the member itself keeps the real label the viewer needs). The Interface canvas is deliberately
 * absent — its standalone equivalent is the Module block.
 */
declare enum ArtifactTypeEnum {
    Html = "HTML",
    Markdown = "MARKDOWN",
    Json = "JSON",
    Pdf = "PDF",
    Docx = "DOCX",
    Pptx = "PPTX",
    Sheet = "SHEET",
    Url = "URL",
    Email = "EMAIL",
    Flow = "FLOW",
    Playbook = "PLAYBOOK"
}
/** What the viewers read. Derived from the artifact record — never maker-authored, so it has no panel fields. */
type ArtifactContent = {
    artifactType?: ArtifactTypeEnum | (string & {});
    fileUrl?: string;
    downloadUrl?: string;
    fileName?: string;
    attributes?: IframeAttributes;
    entityId?: string;
    entityType?: string;
    entityVersion?: number;
    entityProperties?: Record<string, unknown>;
};

