type BaseCanvasState = {
    messageId?: string;
    size?: CanvasSize;
    width?: string;
    artifact?: ArtifactMetadata;
};
type InterfacePageCanvasState = BaseCanvasState & Extract<CanvasContent, {
    type: CanvasType.Interface;
}>;
type CopilotPreviewCanvas = (BaseCanvasState & CanvasContent) | null;
type FileCanvasState = Exclude<CopilotPreviewCanvas, InterfacePageCanvasState | null>;

/**
 * The file/embed artifact shapes both surfaces render. The canvas-state types in carbon stay the
 * source of truth (the copilot preview provider owns their lifecycle); this union is the subset a
 * standalone artifact surface can show — the Interface canvas stays copilot-only (page embedding
 * for makers is the Module block).
 */
type ArtifactState = FileCanvasState;
interface ArtifactMaximizeState {
    isMaximized: boolean;
    onToggle: (maximized: boolean) => void;
    hideToggle?: boolean;
}

/** What the read resolved to. A gone record and a refused one are answers, not failures. */
type EntityAvailability = 'available' | 'deleted' | 'forbidden';

interface ArtifactRecord {
    artifact: ArtifactState | undefined;
    availability: EntityAvailability | undefined;
    isLoading: boolean;
}
/**
 * Read live, never deployed: deployed is only the publish signal, the record carries the file.
 */
declare function useArtifactRecord(artifactId: string | undefined): ArtifactRecord;

/**
 * Maps artifact content onto the same artifact-state union the copilot canvas stores, so the
 * shared ArtifactViewer renders both surfaces through one code path. Returns undefined when the
 * content names no file — the block then shows a builder-only placeholder and renders nothing in
 * a deployed app.
 */
declare function getArtifactState(content: ArtifactContent): ArtifactState | undefined;

interface ArtifactViewerProps {
    artifact: ArtifactState;
    className?: string;
    onClose?: () => void;
    maximize?: ArtifactMaximizeState;
    hideHeader?: boolean;
    onEmbedLoad?: () => void;
    embedFrameKey?: Key;
    setIframeRef?: Dispatch<SetStateAction<HTMLIFrameElement | null>>;
    onRefresh?: () => void;
    onAskForChanges?: (text: string, subject: string) => void;
    onEditSelection?: (selectedText: string, describeText: string, subject: string) => void;
    onRequestConnection?: (provider?: string) => void;
    onSubmitEdits?: (message: string) => void;
    aiAgentId?: string;
    disableRotate?: boolean;
    openCitationsDrawer?: () => void;
}
/**
 * The one artifact dispatch both surfaces share: the copilot canvas (CopilotCanvas translates
 * preview context into these props) and the Artifact block (maker config). Prop-driven, except
 * the header's self-gating copilot controls (see ArtifactHeader), which render nothing outside a
 * copilot. The Interface canvas is deliberately not here:
 * embedding an interface page standalone is the Module block.
 */
declare function ArtifactViewer({ artifact, className, onClose, maximize, hideHeader, onEmbedLoad, embedFrameKey, setIframeRef, onRefresh, onAskForChanges, onEditSelection, onRequestConnection, onSubmitEdits, aiAgentId, disableRotate, openCitationsDrawer, }: ArtifactViewerProps): react_jsx_runtime.JSX.Element | null;

interface ArtifactProps {
    /** The artifact record to preview — an `e_artifact_detail` id (what the copilot's publish
     * step returns). The record carries the file: its type, the rendered `previewUrl`
     * (PPTX/DOCX are pre-converted to PDF) and the original `downloadUrl`. */
    artifactId: string | undefined;
    className?: string;
    /** Fires when the viewer's close control is used. The cross only REPORTS intent — wire this
     * to hide, remove or navigate away from the panel. Omit it and no cross is shown. */
    onClose?: () => void;
    /** Which color scheme the viewer renders in. Defaults to `system`. Scoped to the viewer's
     * own root, so it never flips the host app's scheme. */
    colorScheme?: CopilotColorScheme;
    /** Writing direction for the viewer subtree. Omit to inherit the document's own `dir`. */
    dir?: 'ltr' | 'rtl';
}
/** The no-code Artifact viewer, standalone.
 *
 * Point it at an `artifactId` and it renders the same PPTX/DOCX/PDF/Sheet/Email/… surface the
 * copilot canvas and the low-code Artifact block render — the identical `ArtifactViewer`, not a
 * re-implementation. It brings its own provider stack (theme, i18n, query client, resource
 * strategy) because a host app has none of that, and scopes the design-system theme to its own
 * root so it never touches the host's styles.
 *
 * The fetch is the same one the block uses (`useArtifactRecord`): it reads the record through the
 * platform's FETCH_ENTITY_BY_ID automation, so an app user who holds no entity-type grant still
 * resolves the file. That automation must be registered on the environment — where it is not, the
 * read falls back to the entity API and a grant-less reader gets the unavailable state. */
declare function Artifact({ artifactId, className, onClose, colorScheme, dir }: ArtifactProps): react_jsx_runtime.JSX.Element;

export { Artifact, ArtifactViewer, getArtifactState, useArtifactRecord };
export type { ArtifactContent, ArtifactProps, ArtifactState, ArtifactViewerProps };
